def resolve(path, cwd, links):
    # Follow at most 8 links
    link_count = [0]

    def resolve_path(p):
        # Normalize and split into components
        if p.startswith('/'):
            current = '/'
            components = [c for c in p.split('/') if c and c != '.']
        else:
            current = cwd
            components = [c for c in p.split('/') if c and c != '.']

        i = 0
        while i < len(components):
            component = components[i]

            if component == '..':
                # Move to parent, but '/' stays '/'
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
            else:
                # Append component
                if current == '/':
                    current = '/' + component
                else:
                    current = current + '/' + component

                # Check if current is a symlink
                if current in links:
                    link_count[0] += 1
                    if link_count[0] > 8:
                        return None

                    target = links[current]
                    remaining = components[i + 1:]

                    # Resolve the target relative to the directory containing the link
                    if target.startswith('/'):
                        current = '/'
                        target_components = [c for c in target.split('/') if c and c != '.']
                    else:
                        # Relative to directory containing the link
                        if current == '/':
                            current = '/'
                        else:
                            current = current.rsplit('/', 1)[0]
                            if not current:
                                current = '/'
                        target_components = [c for c in target.split('/') if c and c != '.']

                    # Replace current components with target + remaining
                    components = target_components + remaining
                    i = 0
                    continue

            i += 1

        return current if current else '/'

    result = resolve_path(path)

    # Remove trailing slash except for '/'
    if result and result != '/' and result.endswith('/'):
        result = result.rstrip('/')

    return result

